INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65659797', 65659797, 'analyze_legacy', 'Kota Banjar', 'kabkota', 'UPTD RUMAH SAKIT UMUM', 'Belanja Makan Minum Rapat', 'Barang', 'E-Purchasing', 'Jawa Barat, Banjar (Kota)', 25000000, 'January 2026', 'BLUD', 1, 1, '1 Tahun', 'Penyediaan konsumsi untuk kegiatan rapat, koordinasi, sosialisasi, dan pertemuan resmi lainnya guna mendukung kelancaran pelaksanaan tugas dan fungsi instansi. Pekerjaan meliputi penyediaan makanan ringan dan/atau makan lengkap beserta minuman sesuai jumlah peserta dan durasi kegiatan, dengan memperhatikan standar kebersihan, kualitas, dan ketepatan waktu distribusi selama tahun anggaran berjalan sesuai ketentuan yang berlaku.', 'Penyediaan konsumsi berupa makanan ringan dan/atau makan lengkap beserta minuman sesuai jumlah peserta dan jenis kegiatan, dengan kualitas bahan yang baik, higienis, dan layak konsumsi sesuai standar keamanan pangan. Penyedia wajib menyiapkan dan mendistribusikan konsumsi tepat waktu sesuai jadwal rapat, dalam kemasan atau penyajian yang rapi dan aman, serta menyerahkan rekap jumlah porsi sebagai dasar pembayaran sesuai ketentuan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2255297);
