INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65621144', 65621144, 'analyze_legacy', 'Kota Banjar', 'kabkota', 'UPTD RUMAH SAKIT UMUM', 'Belanja Jasa Pendampingan Hukum', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Jawa Barat, Banjar (Kota)', 65000000, 'January 2026', 'BLUD', 1, 1, '1 Tahun', 'Penyediaan tenaga ahli hukum yang kompeten untuk memberikan pendampingan, telaah dan opini hukum, asistensi penyusunan dokumen hukum, klarifikasi terhadap permasalahan hukum, serta pendampingan dalam proses mediasi, negosiasi, atau penanganan sengketa sesuai kebutuhan instansi selama tahun anggaran berjalan. Layanan dilaksanakan secara profesional dan independen guna mendukung kepastian hukum, mitigasi risiko, serta perlindungan kepentingan institusi sesuai ketentuan peraturan perundang-undangan.', 'Tenaga ahli hukum yang memiliki kualifikasi pendidikan dan/atau izin praktik yang sah serta pengalaman relevan, untuk memberikan layanan konsultasi, telaah dan opini hukum tertulis, asistensi penyusunan dan reviu dokumen/perjanjian, pendampingan dalam klarifikasi, mediasi atau proses sengketa, serta pemberian rekomendasi mitigasi risiko hukum. Penyedia wajib menjamin kerahasiaan informasi, responsivitas layanan sesuai kebutuhan instansi, serta menyerahkan laporan hasil pendampingan atau dokumen opini hukum sebagai output pekerjaan selama masa kontrak.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2256941);
